    "sopRecord":  "Alabama commercial permit holders record every application, restricted use or not: the EPA registration number, the amount used, the crop or site, the pest, the rate, the location, and the date and time. Keep these records at least 3 years (Ala. Admin. Code 80-1-13-.14). The Professional Services rule (80-10-9-.15) also asks for the owner\u0027s and permittee\u0027s names and addresses and the type of work, and keeps termite contracts 1 year past expiration and monthly termite reports 3 years.",
