    "sopRecord":  "Pennsylvania businesses record every application within 24 hours and keep the record at least 3 years. Each record shows the date (and the hour finished if the label has a reentry time), the customer\u0027s name and address and the site address if different, the brand name, the EPA registration number, the total amount used, the dosage or rate, and the names and certification or technician registration numbers of everyone applying or supervising. Records must be available to PDA immediately on request and to medical personnel immediately in an emergency (7 Pa. Code 128.35). Hypersensitivity notices also need a record of each contact and attempt.",
