    "sopRecord":  "Utah commercial applicators write each record within 24 hours and keep it at least 2 years in a uniform format. Each record shows the customer\u0027s name and address, the application address if different, the total square footage or size treated, the target sites, the time and date, the brand name, EPA registration number and mix rate, the total amount applied per location and per application, the purpose and pest, and the applicator\u0027s name, business address and license number (Utah Admin. Code R68-7-11(11)). Termite jobs add a diagram of the structure with dimensions and depth to the footer, filed by structure for 2 years (R68-7-17).",
